    "adj_tab3_sub": "Choice & Sentence Builder",
    "adj_p1_hero_title": "How do we compare things in Danish?",
    "adj_p1_hero_desc": "Adjectives describe how someone or something is. When we want to compare or highlight qualities, we inflect adjectives in <strong>three steps</strong>:<br><strong>1. Base form (Positive):</strong> Describes just one thing without comparison (e.g. <em>en stor bil</em>).<br><strong>2. Comparative:</strong> Used when comparing <strong>two things</strong>. We almost always use the word <strong>\"end\"</strong> (e.g. <em>Bilen er <strong>større end</strong> cyklen</em>).<br><strong>3. Superlative (The Winner):</strong> Used when one thing <strong>exceeds all others</strong> and reaches the highest degree (e.g. <em>Lastbilen er <strong>størst</strong></em>).",
    "adj_p1_rule_thumb_label": "Rule of thumb:",
    "adj_p1_rule_thumb_text": "Comparative compares 2 things with <strong>\"end\"</strong>. Superlative crowns the winner that exceeds all!",
    "adj_p1_s1_title_fagterm": "Positive (base form)",
    "adj_p1_s1_title_everyday": "1. Normal description",
    "adj_p1_s1_q": "Are you describing just one thing?",
    "adj_p1_s1_ans": "Yes ➔ Use base form (\"stor / hurtig / kold\")",
    "adj_p1_s1_badge_fagterm": "Positive (base form)",
    "adj_p1_s1_badge_everyday": "1. Describes 1 thing",
    "adj_p1_s2_title_fagterm": "Comparative",
    "adj_p1_s2_title_everyday": "2. Comparing two things",
    "adj_p1_s2_q": "Are you comparing two things? (Look for the word \"end\")",
    "adj_p1_s2_ans": "Yes ➔ Add -ere or vowel shift (\"større / hurtigere\")",
    "adj_p1_s2_badge_fagterm": "Comparative (comparison form)",
    "adj_p1_s2_badge_everyday": "2. Compares 2 things",
    "adj_p1_s3_title_fagterm": "Superlative (highest degree)",
    "adj_p1_s3_title_everyday": "3. Winner / exceeds all",
    "adj_p1_s3_q": "Does it exceed everything else in the group?",
    "adj_p1_s3_ans": "Yes ➔ Add -est or vowel shift (\"størst / hurtigst\")",
    "adj_p1_s3_badge_fagterm": "Superlative (highest degree)",
    "adj_p1_s3_badge_everyday": "3. Winner exceeds all",
    "adj_p1_flow_label": "Natural comparison flow in a conversation:",
