    "adj_p1_explorer_desc": "Click on an adjective below to see how the scale grows from positive to comparative and superlative:",
    "adj_listen_btn_short": "Listen",
    "adj_p2_hero_title": "The Definite -E Rule: Why does it say \"den store bil\" and \"min store bil\"?",
    "adj_p2_hero_desc": "In Danish, an adjective must change into its <strong>definite form</strong> by adding <strong>-e</strong> whenever the topic is made specific or owned!<br>• <strong>Indefinite:</strong> <em>en stor bil</em> (fælleskøn) | <em>et stort hus</em> (-t in intetkøn).<br>• <strong>Definite:</strong> As soon as we make it definite with an article (<em>den/det/de</em>), a possessive pronoun (<em>min/din/vores</em>), a demonstrative (<em>denne/dette</em>), or a name in genitive (<em>Peters</em>), <strong>the adjective ALWAYS adds -e</strong> regardless of gender!",
    "adj_p2_formula_title": "📐 The Definite Adjective Formula:",
    "adj_p2_chip_marker_fagterm": "Definite marker",
    "adj_p2_chip_marker_everyday": "Known or owned",
    "adj_p2_chip_adj_fagterm": "Adjective + -E",
    "adj_p2_chip_adj_everyday": "Description + -E",
    "adj_p2_chip_noun_fagterm": "Noun",
    "adj_p2_chip_noun_everyday": "Noun",
    "adj_p2_formula_note": "💡 <strong>Remember:</strong> In the definite form, neuter words drop their \"-t\" (<em>et stor<strong>t</strong> hus</em> ➔ <em>det stor<strong>e</strong> hus</em> / <em>mit stor<strong>e</strong> hus</em>)!",
