    "adj_p2_super_def_badge": "🌟 Definite Superlative:",
    "adj_p2_super_def_title": "Also adds -e: \"Den største bil\" & \"Min bedste ven\"",
    "adj_p2_super_def_text": "When a superlative is used with a definite article (<em>den/det/de</em>) or possessive pronoun (<em>min/din</em>), it also gets the ending <strong>-e</strong>!<br>• Alone / Predicative: <em>Lastbilen er <strong>størst</strong>.</em><br>• Definite with article: <em>Det er <strong>den største</strong> lastbil på vejen.</em><br>• With possessive pronoun: <em>Peter er <strong>min bedste</strong> ven.</em>",
    "adj_p2_super_def_listen": "Listen to examples",
