    "adj_p1_hero_title": "Wie vergleicht man Dinge auf Dänisch?",
    "adj_p1_hero_desc": "Adjektive (Eigenschaftswörter) beschreiben, wie etwas ist. Wenn wir Eigenschaften vergleichen oder hervorheben möchten, steigern wir das Adjektiv in <strong>drei logischen Stufen</strong>:<br><strong>1. Grundform (Positiv):</strong> Beschreibt einfach eine Sache für sich allein (z. B. <em>en stor bil</em>).<br><strong>2. Vergleich (Komparativ):</strong> Wird verwendet, wenn wir <strong>zwei Dinge</strong> vergleichen. Wir benutzen fast immer das Wort <strong>„end“</strong> (z. B. <em>Bilen er <strong>større end</strong> cyklen</em>).<br><strong>3. Der Sieger (Superlativ):</strong> Wird verwendet, wenn etwas <strong>alle anderen übertrifft</strong> und auf der allerhöchsten Stufe steht (z. B. <em>Lastbilen er <strong>størst</strong></em>).",
    "adj_p1_rule_thumb_label": "Faustregel:",
