    "adj_p2_hero_desc": "Wenn ein Substantiv unbestimmt und unbekannt ist, steht das Adjektiv in seiner Grundform (oder erhält bei Neutrum ein -t):<br>• <strong>Unbestimmt:</strong> <em>en stor bil</em> (fælleskøn) | <em>et stort hus</em> (intetkøn erhält -t).<br>• <strong>Aber wenn der Gegenstand BESTIMMT ist:</strong> Sobald der Gegenstand bekannt ist, hervorgehoben oder besessen wird, MUSS das Adjektiv immer ein <strong>-e</strong> erhalten – ganz egal, ob fælleskøn oder intetkøn!<br><em>den stor<strong>e</strong> bil</em> • <em>det stor<strong>e</strong> hus</em> • <em>min stor<strong>e</strong> bil</em> • <em>denne stor<strong>e</strong> bil</em>",
