    "adj_p3_puz4_meaning": "Diese schöne Blume duftet im Garten am besten.",
    "adj_p3_puz4_hint": "„Denne“ löst das -e aus („smukke“), während „bedst“ der Superlativ ist.",
    "adj_q_s1_q1_feedback": "Richtig! Das Wort ‚end‘ zeigt, dass zwei Dinge verglichen werden ➔ Komparativ verwenden (hurtigere).",
    "adj_q_s1_q1_hint_hurtig": "Nicht vergessen: Das Wort ‚end‘ zeigt, dass zwei Dinge verglichen werden. Wir müssen also die Komparativform verwenden.",
    "adj_q_s1_q1_hint_hurtigst": "Wir vergleichen hier nur zwei Dinge. Der Superlativ wird verwendet, wenn etwas alle anderen übertrifft.",
    "adj_q_s1_q2_feedback": "Richtig! Das Wort ‚sin‘ ist ein Possessivpronomen (Besitzwort) ➔ das Adjektiv muss ein -e erhalten!",
