    "adj_q_s1_q5_feedback": "Richtig! Zwei Tage werden mit ‚end‘ verglichen ➔ Komparativ (koldere).",
    "adj_q_s1_q5_hint_kold": "Im Satz steht ‚end‘, wir vergleichen also das Wetter von heute mit dem von gestern.",
    "adj_q_s1_q5_hint_koldest": "Wir vergleichen zwei Tage. Der Superlativ wird verwendet, wenn es der kälteste Tag des Jahres wäre.",
