    "adj_q_s2_q4_hint_bedre": "‚Bedre‘ wird nur beim direkten Vergleich mit ‚end‘ verwendet.",
    "adj_q_s2_q5_feedback": "Richtig! ‚Det‘ ist ein bestimmter Artikel ➔ das Adjektiv muss immer ein -e erhalten (det hvide hus).",
