    "adj_q_s4_q3_hint_tungest": "Wir vergleichen hier nur zwei Dinge.",
    "adj_q_s4_q4_feedback": "Richtig! Der bestimmte Artikel ‚den‘ verlangt immer ein -e am Adjektiv (den røde blyant).",
