    "adj_p1_hero_title": "¿Cómo comparamos cosas en danés?",
    "adj_p1_hero_desc": "Los adjetivos describen cómo es algo. Cuando queremos comparar o resaltar cualidades, graduamos el adjetivo en <strong>tres pasos lógicos</strong>:<br><strong>1. Forma base (Positivo):</strong> Describe solo una cosa por sí misma (p. ej., <em>en stor bil</em>).<br><strong>2. Comparación (Comparativo):</strong> Se usa cuando comparamos <strong>dos cosas</strong>. Casi siempre usamos la palabra <strong>\"end\"</strong> (p. ej., <em>Bilen er <strong>større end</strong> cyklen</em>).<br><strong>3. El ganador (Superlativo):</strong> Se usa cuando algo <strong>supera a todos los demás</strong> y alcanza el grado más alto (p. ej., <em>Lastbilen er <strong>størst</strong></em>).",
