    "adj_p2_hero_desc": "Cuando un sustantivo es indeterminado y desconocido, el adjetivo mantiene su forma base (o añade -t con género neutro):<br>• <strong>Indeterminado:</strong> <em>en stor bil</em> (fælleskøn) | <em>et stort hus</em> (intetkøn añade -t).<br>• <strong>Pero cuando el elemento es DETERMINADO:</strong> Tan pronto como el elemento es conocido, señalado o poseído, el adjetivo SIEMPRE DEBE llevar <strong>-e</strong>, ¡sin importar si es fælleskøn o intetkøn!<br><em>den stor<strong>e</strong> bil</em> • <em>det stor<strong>e</strong> hus</em> • <em>min stor<strong>e</strong> bil</em> • <em>denne stor<strong>e</strong> bil</em>",
