    "adj_p1_hero_title": "Como comparamos coisas em dinamarquês?",
    "adj_p1_hero_desc": "Os adjetivos descrevem como algo é. Quando queremos comparar ou destacar qualidades, flexionamos o adjetivo em <strong>três etapas lógicas</strong>:<br><strong>1. Forma básica (Positivo):</strong> Descreve apenas uma coisa por si só (ex.: <em>en stor bil</em>).<br><strong>2. Comparação (Comparativo):</strong> Usado quando comparamos <strong>duas coisas</strong>. Quase sempre usamos a palavra <strong>\"end\"</strong> (ex.: <em>Bilen er <strong>større end</strong> cyklen</em>).<br><strong>3. O vencedor (Superlativo):</strong> Usado quando algo <strong>supera todos os outros</strong> e alcança o grau mais alto (ex.: <em>Lastbilen er <strong>størst</strong></em>).",
