    "adj_listen_btn_short": "Ouvir",
    "adj_p2_hero_title": "A regra de ouro do -e: por que se diz \"den store bil\" e \"min store bil\"?",
    "adj_p2_hero_desc": "Quando um substantivo é indefinido e desconhecido, o adjetivo mantém sua forma básica (ou recebe -t no gênero neutro):<br>• <strong>Indefinido:</strong> <em>en stor bil</em> (fælleskøn) | <em>et stort hus</em> (intetkøn recebe -t).<br>• <strong>Mas quando o item é DEFINIDO:</strong> Assim que o item se torna conhecido, apontado ou possuído, o adjetivo DEVE sempre receber <strong>-e</strong> — independentemente de ser fælleskøn ou intetkøn!<br><em>den stor<strong>e</strong> bil</em> • <em>det stor<strong>e</strong> hus</em> • <em>min stor<strong>e</strong> bil</em> • <em>denne stor<strong>e</strong> bil</em>",
