    "adj_p1_hero_title": "Dancada nesneleri ve durumları nasıl karşılaştırırız?",
    "adj_p1_hero_desc": "Sıfatlar bir şeyin nasıl olduğunu tanımlar. Özellikleri karşılaştırmak veya öne çıkarmak istediğimizde, sıfatı <strong>üç mantıksal aşamada</strong> derecelendiririz:<br><strong>1. Temel hal (Pozitif):</strong> Yalnızca tek bir şeyi kendi başına tanımlar (örn. <em>en stor bil</em>).<br><strong>2. Karşılaştırma (Komparatif):</strong> <strong>İki şeyi</strong> karşılaştırırken kullanılır. Neredeyse her zaman <strong>\"end\"</strong> (daha / -den) kelimesini kullanırız (örn. <em>Bilen er <strong>større end</strong> cyklen</em>).<br><strong>3. Birinci (Süperlatif):</strong> Bir şey <strong>diğer hepsini geride bıraktığında</strong> ve en üst basamakta olduğunda kullanılır (örn. <em>Lastbilen er <strong>størst</strong></em>).",
