    "adj_listen_btn_short": "Dinle",
    "adj_p2_hero_title": "Altın -e kuralı: Neden \"den store bil\" ve \"min store bil\" denir?",
    "adj_p2_hero_desc": "Bir isim belirsiz ve bilinmeyen olduğunda, sıfat temel halini korur (veya nötr cinste -t alır):<br>• <strong>Belirsiz:</strong> <em>en stor bil</em> (fælleskøn) | <em>et stort hus</em> (intetkøn -t alır).<br>• <strong>Fakat nesne BELİRLİ olduğunda:</strong> Nesne bilinen, işaret edilen veya sahiplenilen hale geldiği anda, sıfat cinsiyetine (fælleskøn veya intetkøn) bakılmaksızın MUTLAKA <strong>-e</strong> eki almalıdır!<br><em>den stor<strong>e</strong> bil</em> • <em>det stor<strong>e</strong> hus</em> • <em>min stor<strong>e</strong> bil</em> • <em>denne stor<strong>e</strong> bil</em>",
