    "adj_p2_hero_desc": "عندما يكون الاسم نكرة وغير معروف، تأخذ الصفة صيغتها الأساسية (أو -t مع الجنس المحايد):<br>• <strong>نكرة (Ubestemt):</strong> <em>en stor bil</em> (مشترك) | <em>et stort hus</em> (المحايد يأخذ -t).<br>• <strong>ولكن عندما يكون الشيء مَعْرِفَة (BESTEMT):</strong> بمجرد أن يصبح الشيء معروفًا أو محددًا أو مملوكًا، يَجِب أن تأخذ الصفة دائمًا اللاحقة <strong>-e</strong> – سواء كان الاسم مشتركًا أم محايدًا!<br><em>den stor<strong>e</strong> bil</em> • <em>det stor<strong>e</strong> hus</em> • <em>min stor<strong>e</strong> bil</em> • <em>denne stor<strong>e</strong> bil</em>",
