    "adj_p3_puz4_hint": "\"Denne\" تتطلب إضافة -e (\"smukke\")، بينما \"bedst\" هي صيغة تفضيل (superlativ).",
    "adj_q_s1_q1_feedback": "صحيح! كلمة 'end' تدل على مقارنة شيئين ➔ استخدم صيغة المقارنة (hurtigere).",
    "adj_q_s1_q1_hint_hurtig": "تذكر: كلمة 'end' تدل على مقارنة شيئين. لذلك يجب استخدام صيغة المقارنة.",
    "adj_q_s1_q1_hint_hurtigst": "نحن نقارن بين شيئين فقط هنا. تُستخدم صيغة التفضيل عندما يتفوق شيء على كل الآخرين.",
    "adj_q_s1_q2_feedback": "صحيح! كلمة 'sin' هي ضمير ملكية ➔ يجب أن تأخذ الصفة اللاحقة -e!",
    "adj_q_s1_q2_hint_ny": "توجد هنا 'sin' (ضمير ملكية). عندما يكون الشيء مملوكًا أو معرفة، يجب أن تأخذ الصفة دائمًا -e.",
    "adj_q_s1_q2_hint_nyt": "'En bil' من الجنس المشترك، ولكن الأهم: مع 'sin' يُضاف دائمًا -e (مثل den nye bil / sin nye bil).",
    "adj_q_s1_q3_feedback": "صحيح! جبل إفرست يتفوق على جميع الجبال الأخرى ➔ يأخذ الفائز صيغة التفضيل المعرفة (-este).",
    "adj_q_s1_q3_hint_høj": "نحن نتحدث عن جميع جبال العالم، لذا فهو أعلى جبل على الإطلاق بين الجميع.",
    "adj_q_s1_q3_hint_højere": "نحن لا نقارن بين جبلين فقط. جبل إفرست هو رقم 1 بين الجميع.",
    "adj_q_s1_q4_feedback": "صحيح! 'Den' هي أداة تعريف ➔ يجب أن تنتهي الصفة دائمًا بـ -e (gamle).",
    "adj_q_s1_q4_hint_gammel": "توجد هنا أداة التعريف 'den'. في صيغة المعرفة يجب أن تأخذ الصفة اللاحقة -e.",
    "adj_q_s1_q4_hint_gammelt": "تُستخدم -t مع الجنس المحايد النكرة (et gammelt hus)، وليس مع 'den dame'.",
    "adj_q_s1_q5_feedback": "صحيح! تتم المقارنة بين يومين باستخدام 'end' ➔ استخدم صيغة المقارنة (koldere).",
    "adj_q_s1_q5_hint_kold": "توجد كلمة 'end' في الجملة، لذا فنحن نقارن طقس اليوم بالأمس.",
    "adj_q_s1_q5_hint_koldest": "نحن نقارن بين يومين. تُستخدم صيغة التفضيل إذا كان هذا أبرد يوم في السنة.",
    "adj_q_s2_q1_feedback": "صحيح! 'En taske' اسم نكرة من الجنس المشترك ➔ الصفة في صيغتها الأساسية (dyr).",
    "adj_q_s2_q1_hint_dyrt": "'En taske' من الجنس المشترك (en)، لذا لا تأخذ -t.",
    "adj_q_s2_q1_hint_dyre": "الحديث هنا عن حقيبة واحدة نكرة، لذا لا نضيف -e.",
    "adj_q_s2_q2_feedback": "صحيح! 'Denne' اسم إشارة ➔ يجب أن تأخذ الصفة اللاحقة -e (flotte).",
    "adj_q_s2_q2_hint_flot": "عند استخدام 'denne/dette'، يكون الشيء معرفة، ويجب أن تأخذ الصفة دائمًا -e.",
    "adj_q_s2_q2_hint_flottere": "نحن لا نقارن بين دراجتين هنا، بل نشير فقط إلى هذه الدراجة الجميلة.",
    "adj_q_s2_q3_feedback": "صحيح! مقارنة بين حيوانين باستخدام 'end' ➔ استخدم صيغة المقارنة (større).",
    "adj_q_s2_q3_hint_stor": "توجد كلمة 'end'، لذا تتم المقارنة بين الحيوانين.",
    "adj_q_s2_q3_hint_størst": "نحن نقارن بين حيوانين فقط. تُستخدم 'størst' للفائز في مجموعة كاملة.",
    "adj_q_s2_q4_feedback": "صحيح! 'Min bedste ven' هي صيغة تفضيل معرفة (الصديق الذي يتفوق على جميع الآخرين).",
    "adj_q_s2_q4_hint_god": "نحن هنا نختار الصديق الذي يحتل المرتبة الأولى بين الجميع.",
    "adj_q_s2_q4_hint_bedre": "تُستخدم 'Bedre' فقط في المقارنة المباشرة مع 'end'.",
    "adj_q_s2_q5_feedback": "صحيح! 'Det' هي أداة تعريف ➔ يجب أن تأخذ الصفة دائمًا اللاحقة -e (det hvide hus).",
    "adj_q_s2_q5_hint_hvid": "أداة التعريف 'det' تجعل الاسم معرفة، لذا يجب أن تأخذ الصفة -e.",
    "adj_q_s2_q5_hint_hvidt": "في النكرة نقول 'et hvidt hus'، ولكن في صيغة المعرفة مع 'det' تختفي -t وتتحول إلى -e.",
    "adj_q_s3_q1_feedback": "صحيح! الفهد يتفوق على جميع الحيوانات البرية الأخرى على الأرض ➔ الفائز يأخذ صيغة التفضيل المعرفة (-este).",
    "adj_q_s3_q1_hint_hurtig": "الفهد هو الأسرع على الإطلاق بين جميع الحيوانات البرية.",
    "adj_q_s3_q1_hint_hurtigere": "نحن لا نقارنه بحيوان واحد آخر فقط، بل نتوّج الفائز على وجه الأرض.",
    "adj_q_s3_q2_feedback": "صحيح! 'Min' ضمير ملكية ➔ يجب أن تأخذ الصفة دائمًا اللاحقة -e!",
    "adj_q_s3_q2_hint_varm": "توجد كلمة 'min' (ضمير ملكية). عندما يكون الشيء مملوكًا، يجب أن تأخذ الصفة -e.",
    "adj_q_s3_q2_hint_varmt": "'Jakke' كلمة من الجنس المشترك (en-ord)، و 'min' تتطلب اللاحقة -e (مثل min varme jakke).",
    "adj_q_s3_q3_feedback": "صحيح! تتم المقارنة بين التفاحة والكمثرى باستخدام 'end' ➔ صيغة المقارنة (sødere).",
    "adj_q_s3_q3_hint_sød": "كلمة 'end' تشير إلى مقارنة مباشرة بين فاكهتين.",
    "adj_q_s3_q3_hint_sødest": "تُستخدم صيغة التفضيل عندما يكون الشيء هو الأحلى بين كل الأشياء.",
    "adj_q_s3_q4_feedback": "صحيح! 'Et barn' اسم نكرة من الجنس المحايد ➔ تأخذ الصفة -t (gladt).",
    "adj_q_s3_q4_hint_glad": "'Et barn' اسم محايد، لذا يجب أن تأخذ الصفة -t في صيغة النكرة.",
    "adj_q_s3_q4_hint_glade": "تُستخدم -e في صيغة المعرفة (det glade barn) أو الجمع (glade børn).",
    "adj_q_s3_q5_feedback": "صحيح! 'Peters' صيغة ملكية (genitiv) ➔ يجب أن تأخذ الصفة دائمًا اللاحقة -e!",
    "adj_q_s3_q5_hint_hurtig": "مع الأسماء في صيغة الملكية (Peters)، تنطبق دائمًا قاعدة -e.",
    "adj_q_s3_q5_hint_hurtigt": "تسقط -t في صيغة المعرفة والملكية ➔ ويجب إضافة -e.",
    "adj_q_s4_q1_feedback": "صحيح! هذا اليوم يتفوق على جميع الأيام الـ 364 الأخرى ➔ صيغة التفضيل المعرفة (-este).",
    "adj_q_s4_q1_hint_varm": "يتم اختيار هذا اليوم من بين جميع أيام السنة كأعلى درجة حرارة على الإطلاق.",
    "adj_q_s4_q1_hint_varmere": "نحن لا نقارن بين يومين هنا، بل نتوّج اليوم الفائز على الإطلاق في السنة.",
    "adj_q_s4_q2_feedback": "صحيح! 'Vores' ضمير ملكية ➔ يجب أن تأخذ الصفة اللاحقة -e (gamle).",
    "adj_q_s4_q2_hint_gammel": "توجد هنا كلمة 'vores' (ضمير ملكية). يجب دائمًا إضافة -e إلى الصفة.",
    "adj_q_s4_q2_hint_gammelt": "تُستخدم -t للمحايد فقط في صيغة النكرة ('et gammelt bord')، وليس مع 'vores'.",
    "adj_q_s4_q3_feedback": "صحيح! تتم المقارنة بين شيئين باستخدام 'end' ➔ استخدم صيغة المقارنة (tungere).",
    "adj_q_s4_q3_hint_tung": "كلمة 'end' توضح أن الكتاب والدفتر تتم المقارنة بينهما.",
    "adj_q_s4_q3_hint_tungest": "نحن نقارن بين شيئين فقط هنا.",
    "adj_q_s4_q4_feedback": "صحيح! أداة التعريف 'den' تتطلب دائمًا إضافة -e إلى الصفة (den røde blyant).",
    "adj_q_s4_q4_hint_rød": "توجد أداة التعريف 'den'، لذا يجب أن تأخذ الصفة -e.",
