    "adj_q_s2_q1_hint_dyrt": "'En taske' جنس مشترک (en) است، بنابراین -t نمی‌گیرد.",
    "adj_q_s2_q1_hint_dyre": "در اینجا فقط درباره یک کیف نکره صحبت می‌شود، بنابراین نباید -e بگیرد.",
    "adj_q_s2_q2_feedback": "درست است! 'Denne' یک ضمیر اشاره است ➔ صفت باید -e بگیرد (flotte).",
    "adj_q_s2_q2_hint_flot": "وقتی از 'denne/dette' استفاده می‌کنیم، موضوع معرفه است و صفت همیشه باید -e بگیرد.",
    "adj_q_s2_q2_hint_flottere": "ما در اینجا دو دوچرخه را با هم مقایسه نمی‌کنیم، بلکه فقط به این دوچرخه قشنگ اشاره می‌کنیم.",
    "adj_q_s2_q3_feedback": "درست است! مقایسه دو حیوان با 'end' ➔ از صفت تفضیلی استفاده کنید (større).",
