    "adj_q_s2_q5_hint_hvid": "حرف تعریف 'det' اسم را معرفه می‌کند، بنابراین صفت باید -e بگیرد.",
    "adj_q_s2_q5_hint_hvidt": "حالت نکره 'et hvidt hus' است، اما در شکل معرفه همراه با 'det'، پسوند -t حذف می‌شود و به -e تبدیل می‌گردد.",
    "adj_q_s3_q1_feedback": "درست است! یوزپلنگ از همه حیوانات خشکی‌زی زمین سریع‌تر است ➔ صفت عالی به شکل معرفه می‌آید (-este).",
    "adj_q_s3_q1_hint_hurtig": "یوزپلنگ در میان همه حیوانات خشکی‌زی قطعاً سریع‌ترین است.",
    "adj_q_s3_q1_hint_hurtigere": "ما آن را تنها با یک حیوان دیگر مقایسه نمی‌کنیم، بلکه برترین حیوان روی زمین را مشخص می‌کنیم.",
    "adj_q_s3_q2_feedback": "درست است! 'Min' یک ضمیر ملکی است ➔ صفت همیشه باید -e بگیرد!",
