    "adj_q_s3_q2_hint_varmt": "'Jakke' کلمه‌ای با جنس مشترک (en-ord) است و 'min' نیازمند -e است (min varme jakke).",
    "adj_q_s3_q3_feedback": "درست است! سیب و گلابی با 'end' مقایسه شده‌اند ➔ صفت تفضیلی (sødere).",
