    "adj_q_s3_q4_feedback": "درست است! 'Et barn' اسم نکره جنس خنثی است ➔ صفت -t می‌گیرد (gladt).",
    "adj_q_s3_q4_hint_glad": "'Et barn' جنس خنثی است، بنابراین صفت در حالت نکره باید -t بگیرد.",
    "adj_q_s3_q4_hint_glade": "پسوند -e در شکل معرفه (det glade barn) یا جمع (glade børn) استفاده می‌شود.",
