    "adj_q_s4_q1_feedback": "درست است! این روز از ۳۶۴ روز دیگر سال گرم‌تر است ➔ صفت عالی به شکل معرفه (-este).",
    "adj_q_s4_q1_hint_varm": "این روز در میان تمام روزهای سال به عنوان بالاترین دما شناخته می‌شود.",
    "adj_q_s4_q1_hint_varmere": "ما در اینجا دو روز را مقایسه نمی‌کنیم، بلکه گرم‌ترین روز کل سال را تعیین می‌کنیم.",
    "adj_q_s4_q2_feedback": "درست است! 'Vores' یک ضمیر ملکی است ➔ صفت باید پسوند -e بگیرد (gamle).",
    "adj_q_s4_q2_hint_gammel": "در اینجا 'vores' (ضمیر ملکی) آمده است. صفت همیشه باید -e بگیرد.",
