    "adj_q_s4_q3_hint_tung": "کلمه 'end' نشان می‌دهد که کتاب و دفترچه با هم مقایسه می‌شوند.",
    "adj_q_s4_q3_hint_tungest": "ما در اینجا فقط دو شیء را با هم مقایسه می‌کنیم.",
    "adj_q_s4_q4_feedback": "درست است! حرف تعریف معرفه 'den' همیشه نیازمند -e برای صفت است (den røde blyant).",
    "adj_q_s4_q4_hint_rød": "حرف تعریف 'den' آمده است، بنابراین صفت باید -e بگیرد.",
    "adj_q_s4_q4_hint_rødt": "'Blyant' جنس مشترک است و 'den' همیشه نیازمند -e است.",
    "adj_q_s4_q5_feedback": "درست است! این تکه از همه تکه‌های دیگر روی بشقاب کوچک‌تر است ➔ صفت عالی معرفه (mindste).",
