    "adj_q_s1_q1_feedback": "درست! لفظ 'end' ظاہر کرتا ہے کہ دو چیزوں کا موازنہ ہو رہا ہے ➔ صفت تفضیلی استعمال کریں (hurtigere)۔",
    "adj_q_s1_q1_hint_hurtig": "یاد رکھیں: لفظ 'end' ظاہر کرتا ہے کہ دو چیزوں کا موازنہ ہو رہا ہے۔ لہٰذا ہمیں صفت تفضیلی کی شکل استعمال کرنی چاہیے۔",
    "adj_q_s1_q1_hint_hurtigst": "ہم یہاں صرف دو چیزوں کا موازنہ کر رہے ہیں۔ صفت عالی تب استعمال ہوتی ہے جب کوئی چیز سب پر سبقت رکھتی ہو۔",
    "adj_q_s1_q2_feedback": "درست! لفظ 'sin' ایک ملکیتی ضمیر ہے ➔ صفت پر لازماً -e لگے گا!",
