    "adj_q_s1_q2_hint_nyt": "'En bil' مشترک جنس ہے، لیکن سب سے اہم: 'sin' کے ساتھ ہمیشہ -e کا اضافہ ہوتا ہے (den nye bil / sin nye bil)۔",
    "adj_q_s1_q3_feedback": "درست! ماؤنٹ ایورسٹ باقی تمام پہاڑوں پر سبقت رکھتا ہے ➔ فاتح معرفہ شکل میں صفت عالی (-este) لیتا ہے۔",
