    "adj_q_s1_q4_hint_gammelt": "-t غیر جانبدار نکرہ جنس کے لیے استعمال ہوتا ہے (et gammelt hus)، 'den dame' کے ساتھ نہیں۔",
    "adj_q_s1_q5_feedback": "درست! دو دنوں کا موازنہ 'end' کے ساتھ ہو رہا ہے ➔ صفت تفضیلی (koldere)۔",
    "adj_q_s1_q5_hint_kold": "جملے میں 'end' موجود ہے، اس لیے ہم آج کے موسم کا موازنہ کل سے کر رہے ہیں۔",
