    "adj_q_s4_q4_feedback": "درست! حرف تخصیص 'den' صفت پر ہمیشہ -e کا تقاضا کرتا ہے (den røde blyant)۔",
    "adj_q_s4_q4_hint_rød": "یہاں 'den' (حرف تخصیص) ہے، اس لیے صفت پر -e لگنا چاہیے۔",
    "adj_q_s4_q4_hint_rødt": "'Blyant' مشترک جنس ہے، اور 'den' کے ساتھ ہمیشہ -e درکار ہوتا ہے۔",
    "adj_q_s4_q5_feedback": "درست! یہ ٹکڑا پلیٹ کے دیگر تمام ٹکڑوں سے مختلف (سب سے چھوٹا) ہے ➔ معرفہ صفت عالی (mindste)۔",
    "adj_q_s4_q5_hint_lille": "ہم پلیٹ پر موجود دیگر تمام ٹکڑوں کے مقابلے میں اس کیک کے ٹکڑے کی بات کر رہے ہیں۔",
    "adj_q_s4_q5_hint_mindre": "'Mindre' کا استعمال 'end' کے ساتھ دو ٹکڑوں کا موازنہ کرتے وقت ہوتا ہے۔"
