    "adj_p1_hero_desc": "Прикметники описують якості предметів або людей. Коли ми хочемо порівняти чи підкреслити властивості, ми змінюємо прикметник за <strong>трьома логічними ступенями</strong>:<br><strong>1. Початкова форма (звичайний ступінь):</strong> описує лише один предмет сам по собі (напр., <em>en stor bil</em>).<br><strong>2. Порівняння (вищий ступінь):</strong> вживається при порівнянні <strong>двох предметів</strong>. Ми майже завжди вживаємо слово <strong>«end»</strong> (напр., <em>Bilen er <strong>større end</strong> cyklen</em>).<br><strong>3. Переможець (найвищий ступінь):</strong> вживається, коли предмет <strong>перевершує всіх інших</strong> і перебуває на найвищому рівні (напр., <em>Lastbilen er <strong>størst</strong></em>).",
