    "adj_p1_hero_title": "在丹麦语中我们如何比较事物？",
    "adj_p1_hero_desc": "形容词用来描述事物的特征。当我们想要对比或强调属性时，会将形容词按<strong>三个逻辑递进阶梯</strong>进行变形：<br><strong>1. 原级（基本形式）：</strong>仅描述单独一个事物（例如 <em>en stor bil</em>）。<br><strong>2. 比较级（两者对比）：</strong>用于比较<strong>两个事物</strong>。我们几乎总是搭配单词 <strong>“end”</strong>（例如 <em>Bilen er <strong>større end</strong> cyklen</em>）。<br><strong>3. 最高级（胜出者）：</strong>用于某事物<strong>超越所有其他事物</strong>、处于最高层级时（例如 <em>Lastbilen er <strong>størst</strong></em>）。",
    "adj_p1_rule_thumb_label": "助记口诀：",
    "adj_p1_rule_thumb_text": "比较级用 <strong>“end”</strong> 对比两者。最高级则评选出超越众人的优胜者！",
    "adj_p1_s1_title_fagterm": "原级（基本形式）",
    "adj_p1_s1_title_everyday": "1. 普通描述",
    "adj_p1_s1_q": "你只是单独描述一个事物吗？",
