    "adj_p1_explorer_desc": "点击下方的形容词，查看它如何从原级递进到比较级和最高级：",
    "adj_listen_btn_short": "收听",
    "adj_p2_hero_title": "黄金 -E 规则：为什么说 “den store bil” 和 “min store bil”？",
    "adj_p2_hero_desc": "在丹麦语中，只要事物被具体指明或属于某人，形容词就必须通过加上 <strong>-e</strong> 变成其<strong>定指形式</strong>！<br>• <strong>不定指：</strong><em>en stor bil</em>（通性）| <em>et stort hus</em>（中性加 -t）。<br>• <strong>定指：</strong>只要我们通过冠词（<em>den/det/de</em>）、物主代词（<em>min/din/vores</em>）、指示词（<em>denne/dette</em>）或属格人名（<em>Peters</em>）使其成为定指，<strong>形容词一律加上 -e</strong>，无论性属！",
    "adj_p2_formula_title": "📐 形容词定指形式公式：",
    "adj_p2_chip_marker_fagterm": "定指标记",
    "adj_p2_chip_marker_everyday": "已知或拥有",
    "adj_p2_chip_adj_fagterm": "形容词 + -E",
    "adj_p2_chip_adj_everyday": "描述词 + -E",
    "adj_p2_chip_noun_fagterm": "名词",
    "adj_p2_chip_noun_everyday": "名词（事物名称）",
    "adj_p2_formula_note": "💡 <strong>请记住：</strong>在定指形式中，中性名词会去掉它的 “-t”（<em>et stor<strong>t</strong> hus</em> ➔ <em>det stor<strong>e</strong> hus</em> / <em>mit stor<strong>e</strong> hus</em>）！",
