    "adj_p2_super_def_text": "当最高级形容词与定冠词（<em>den/det/de</em>）或物主代词（<em>min/din/vores</em>）连用时，最高级同样要加上词尾 <strong>-e</strong>！<br>• 单独作表语：<em>Lastbilen er <strong>størst</strong>.</em><br>• 搭配定冠词：<em>Det er <strong>den største</strong> lastbil på vejen.</em><br>• 搭配物主代词：<em>Peter er <strong>min bedste</strong> ven.</em>",
