    "adj_q_s1_q1_feedback": "正确！单词 'end' 表明两者在进行比较 ➔ 使用比较级 (hurtigere)。",
    "adj_q_s1_q1_hint_hurtig": "请记住：单词 'end' 表明两者在比较，因此必须使用比较级形式。",
    "adj_q_s1_q1_hint_hurtigst": "这里只比较两件事物。最高级是在某事物超越所有其他事物时才使用。",
    "adj_q_s1_q2_feedback": "正确！单词 'sin' 是物主代词 ➔ 形容词必须加上 -e！",
    "adj_q_s1_q2_hint_ny": "这里有 'sin'（物主代词）。当事物属于某人或为定指时，形容词一律要加 -e。",
    "adj_q_s1_q2_hint_nyt": "'En bil' 是通性名词，但最重要的是：搭配 'sin' 时一律加 -e（den nye bil / sin nye bil）。",
    "adj_q_s1_q3_feedback": "正确！珠穆朗玛峰超越了其他所有山峰 ➔ 胜出者使用定指最高级形式 (-este)。",
    "adj_q_s1_q3_hint_høj": "我们在谈论全世界的山峰，所以它是所有山峰中绝对最高的一座。",
    "adj_q_s1_q3_hint_højere": "我们不只是在比较两座山。珠穆朗玛峰在所有山峰中位列第一。",
    "adj_q_s1_q4_feedback": "正确！'Den' 是定冠词 ➔ 形容词必须以 -e 结尾 (gamle)。",
    "adj_q_s1_q4_hint_gammel": "这里有冠词 'den'。在定指形式中，形容词必须加上 -e。",
    "adj_q_s1_q4_hint_gammelt": "-t 用于不定指中性名词 (et gammelt hus)，不用于 'den dame'。",
    "adj_q_s1_q5_feedback": "正确！两天用 'end' 进行比较 ➔ 比较级 (koldere)。",
    "adj_q_s1_q5_hint_kold": "句中有 'end'，说明我们在比较今天和昨天的天气。",
    "adj_q_s1_q5_hint_koldest": "我们正在比较两天。如果要表达是一年中最冷的一天，才会用最高级。",
    "adj_q_s2_q1_feedback": "正确！'En taske' 是不定指通性名词 ➔ 形容词使用原级基本形式 (dyr)。",
    "adj_q_s2_q1_hint_dyrt": "'En taske' 是通性名词（en），因此不加 -t。",
    "adj_q_s2_q1_hint_dyre": "这里仅指一个不定指的包，因此不需要加 -e。",
    "adj_q_s2_q2_feedback": "正确！'Denne' 是指示代词 ➔ 形容词必须加 -e (flotte)。",
    "adj_q_s2_q2_hint_flot": "当我们使用 'denne/dette' 时，事物是定指的，形容词始终要加 -e。",
