    "adj_q_s2_q3_hint_størst": "我们只比较两只动物。'Størst' 是用于整个群体中的优胜者。",
    "adj_q_s2_q4_feedback": "正确！'Min bedste ven' 是定指最高级（超越其他所有人的挚友）。",
    "adj_q_s2_q4_hint_god": "这里我们评选的是所有人当中排名第一的挚友。",
    "adj_q_s2_q4_hint_bedre": "'Bedre' 仅用于搭配 'end' 的直接比较。",
    "adj_q_s2_q5_feedback": "正确！'Det' 是定冠词 ➔ 形容词必须加 -e (det hvide hus)。",
