    "adj_q_s3_q1_feedback": "正确！猎豹超越了地球上所有其他陆生动物 ➔ 胜出者使用定指最高级形式 (-este)。",
    "adj_q_s3_q1_hint_hurtig": "猎豹绝对是所有陆地动物中跑得最快的。",
    "adj_q_s3_q1_hint_hurtigere": "我们不仅仅是在把它与另一种动物做对比，而是在评选地球上的绝对第一。",
    "adj_q_s3_q2_feedback": "正确！'Min' 是物主代词 ➔ 形容词必须加 -e！",
    "adj_q_s3_q2_hint_varm": "这里有 'min'（物主代词）。当事物属于某人时，形容词必须加 -e。",
    "adj_q_s3_q2_hint_varmt": "'Jakke' 是通性名词（en-ord），而 'min' 要求加 -e (min varme jakke)。",
    "adj_q_s3_q3_feedback": "正确！苹果和梨用 'end' 进行比较 ➔ 比较级 (sødere)。",
    "adj_q_s3_q3_hint_sød": "单词 'end' 提示这两种水果之间进行直接比较。",
    "adj_q_s3_q3_hint_sødest": "最高级用于某物在所有事物中最甜时。",
    "adj_q_s3_q4_feedback": "正确！'Et barn' 是不定指中性名词 ➔ 形容词加 -t (gladt)。",
    "adj_q_s3_q4_hint_glad": "'Et barn' 是中性名词，所以在不定指形式中形容词必须加 -t。",
    "adj_q_s3_q4_hint_glade": "-e 用于定指形式 (det glade barn) 或复数 (glade børn)。",
    "adj_q_s3_q5_feedback": "正确！'Peters' 是属格（所有格）➔ 形容词必须加上 -e！",
    "adj_q_s3_q5_hint_hurtig": "对于属格人名 (Peters)，-e 规则始终适用。",
    "adj_q_s3_q5_hint_hurtigt": "在定指形式和表达归属时 -t 会脱落 ➔ 必须加上 -e。",
    "adj_q_s4_q1_feedback": "正确！这一天超越了其余 364 天 ➔ 使用定指最高级形式 (-este)。",
    "adj_q_s4_q1_hint_varm": "这一天被评为全年气温绝对最高的一天。",
    "adj_q_s4_q1_hint_varmere": "我们在这里不是在对比两天，而是在评选全年的绝对优胜者。",
    "adj_q_s4_q2_feedback": "正确！'Vores' 是物主代词 ➔ 形容词必须加 -e (gamle)。",
    "adj_q_s4_q2_hint_gammel": "这里是 'vores'（物主代词）。形容词一律要加 -e。",
    "adj_q_s4_q2_hint_gammelt": "中性词尾 -t 仅用于不定指形式 ('et gammelt bord')，不与 'vores' 连用。",
    "adj_q_s4_q3_feedback": "正确！两个物品用 'end' 进行比较 ➔ 使用比较级 (tungere)。",
    "adj_q_s4_q3_hint_tung": "单词 'end' 表明书本和笔记本在做比较。",
    "adj_q_s4_q3_hint_tungest": "我们在这里只比较两件物品。",
    "adj_q_s4_q4_feedback": "正确！定冠词 'den' 始终要求形容词加 -e (den røde blyant)。",
    "adj_q_s4_q4_hint_rød": "这里有 'den'（定冠词），所以形容词必须加 -e。",
    "adj_q_s4_q4_hint_rødt": "'Blyant' 是通性名词，而 'den' 始终要求加 -e。",
    "adj_q_s4_q5_feedback": "正确！这块蛋糕超越了盘子里的所有其他块 ➔ 定指最高级 (mindste)。",
    "adj_q_s4_q5_hint_lille": "我们是在把这块蛋糕与盘子里的所有其他块做比较。",
    "adj_q_s4_q5_hint_mindre": "'Mindre' 用于搭配 'end' 比较两块蛋糕时。"
