    "adj_p1_hero_desc": "Tính từ miêu tả đặc điểm của sự vật hoặc con người. Khi muốn so sánh hoặc nhấn mạnh phẩm chất, chúng ta biến đổi tính từ theo <strong>ba bước logic</strong>:<br><strong>1. Dạng gốc (Cấp nguyên):</strong> Chỉ miêu tả một sự vật riêng lẻ (vd: <em>en stor bil</em>).<br><strong>2. So sánh (Cấp so sánh hơn):</strong> Dùng khi so sánh <strong>hai sự vật</strong>. Chúng ta hầu như luôn dùng từ <strong>\"end\"</strong> (vd: <em>Bilen er <strong>større end</strong> cyklen</em>).<br><strong>3. Quán quân (Cấp so sánh nhất):</strong> Dùng khi một vật <strong>vượt trội hơn tất cả</strong> và đạt mức cao nhất (vd: <em>Lastbilen er <strong>størst</strong></em>).",
