    "adj_tab3_sub": "เลือกรูปคำ & ตัวต่อประโยค",
    "adj_p1_hero_title": "เราเปรียบเทียบสิ่งต่าง ๆ ในภาษาเดนมาร์กอย่างไร?",
    "adj_p1_hero_desc": "คำคุณศัพท์ (tillægsord) บรรยายว่าสิ่งใดสิ่งหนึ่งเป็นอย่างไร เมื่อเราต้องการเปรียบเทียบหรือเน้นคุณสมบัติ เราจะผันคำคุณศัพท์ใน <strong>สามขั้นตอนเชิงตรรกะ</strong>:<br><strong>1. รูปปกติ (Positiv):</strong> บรรยายเพียงสิ่งเดียวโดยไม่เปรียบเทียบ (เช่น <em>en stor bil</em>)<br><strong>2. การเปรียบเทียบ (Komparativ):</strong> ใช้เมื่อเปรียบเทียบ <strong>ของสองสิ่ง</strong> เรามักใช้คำว่า <strong>\"end\"</strong> เสมอ (เช่น <em>Bilen er <strong>større end</strong> cyklen</em>)<br><strong>3. ผู้ชนะ (Superlativ):</strong> ใช้เมื่อมีสิ่งหนึ่ง <strong>เหนือกว่าสิ่งอื่นทั้งหมด</strong> และอยู่ในระดับสูงสุด (เช่น <em>Lastbilen er <strong>størst</strong></em>)",
    "adj_p1_rule_thumb_label": "ข้อควรจำ:",
    "adj_p1_rule_thumb_text": "Komparativ ใช้เปรียบเทียบของ 2 สิ่งด้วยคำว่า <strong>\"end\"</strong> ส่วน Superlativ ใช้ตัดสินผู้ชนะที่เหนือกว่าทั้งหมด!",
    "adj_p1_s1_title_fagterm": "Positiv (รูปปกติ)",
    "adj_p1_s1_title_everyday": "1. การบรรยายทั่วไป",
    "adj_p1_s1_q": "คุณกำลังบรรยายสิ่งของเพียงสิ่งเดียวใช่ไหม?",
