    "adj_p1_explorer_desc": "คลิกคำคุณศัพท์ด้านล่างเพื่อดูว่าระดับขั้นเติบโตจากรูปปกติสู่การเปรียบเทียบและผู้ชนะอย่างไร:",
    "adj_listen_btn_short": "ฟัง",
    "adj_p2_hero_title": "กฎทองของตัว -e: ทำไมถึงเป็น \"den store bil\" และ \"min store bil\"?",
    "adj_p2_hero_desc": "เมื่อคำนามเป็นแบบไม่ชี้เฉพาะและยังไม่ระบุเจาะจง คำคุณศัพท์จะคงรูปปกติ (หรือเติม -t กับเพศกลาง):<br>• <strong>ไม่ชี้เฉพาะ (Ubestemt):</strong> <em>en stor bil</em> (fælleskøn) | <em>et stort hus</em> (intetkøn เติม -t)<br>• <strong>แต่เมื่อเป็นรูปชี้เฉพาะ (BESTEMT):</strong> ทันทีที่สิ่งนั้นเป็นที่รู้จัก ถูกชี้เจาะจง หรือมีเจ้าของ คำคุณศัพท์จะต้องเติม <strong>-e</strong> เสมอ – ไม่ว่าจะเป็น fælleskøn หรือ intetkøn ก็ตาม!<br><em>den stor<strong>e</strong> bil</em> • <em>det stor<strong>e</strong> hus</em> • <em>min stor<strong>e</strong> bil</em> • <em>denne stor<strong>e</strong> bil</em>",
    "adj_p2_formula_title": "📐 สูตรสำหรับรูปชี้เฉพาะของคำคุณศัพท์:",
    "adj_p2_chip_marker_fagterm": "ตัวระบุความชี้เฉพาะ",
    "adj_p2_chip_marker_everyday": "รู้จักแล้วหรือมีเจ้าของ",
    "adj_p2_chip_adj_fagterm": "คำคุณศัพท์ + -E",
