    "adj_p2_chip_noun_everyday": "คำนาม",
    "adj_p2_formula_note": "💡 <strong>ข้อควรจำ:</strong> ในรูปชี้เฉพาะ คำนามเพศกลาง (intetkøn) จะตัด \"-t\" ออก (<em>et stor<strong>t</strong> hus</em> ➔ <em>det stor<strong>e</strong> hus</em> / <em>mit stor<strong>e</strong> hus</em>)!",
    "adj_p2_sc1_title_fagterm": "1. คำกำกับนามชี้เฉพาะ (Bestemt artikel)",
