    "adj_p2_super_def_badge": "🌟 ขั้นสุดในรูปชี้เฉพาะ (Superlativ):",
    "adj_p2_super_def_title": "ต้องเติม -e เสมอเช่นกัน: \"Den største bil\" & \"Min bedste ven\"",
    "adj_p2_super_def_text": "เมื่อคำคุณศัพท์ขั้นสุด (superlativ) ใช้ร่วมกับคำกำกับนามชี้เฉพาะ (<em>den/det/de</em>) หรือคำสรรพนามแสดงความเป็นเจ้าของ (<em>min/din/vores</em>) คำคุณศัพท์ขั้นสุดนั้นจะต้องเติมส่วนท้าย <strong>-e</strong> ด้วยเช่นกัน!<br>• อยู่เดี่ยว ๆ: <em>Lastbilen er <strong>størst</strong>.</em><br>• ชี้เฉพาะด้วยคำนำหน้านาม: <em>Det er <strong>den største</strong> lastbil på vejen.</em><br>• มีคำแสดงความเป็นเจ้าของ: <em>Peter er <strong>min bedste</strong> ven.</em>",
    "adj_p2_super_def_listen": "ฟังตัวอย่าง",
