    "adj_p2_sim_exp_ubestemt_intet": "เพศกลาง (\"et\") ➔ คำคุณศัพท์เติม -t: \"et {adj} {noun}\"",
    "adj_p2_sim_exp_ubestemt_faelles": "เพศร่วม (\"en\") ➔ คำคุณศัพท์ใช้รูปปกติ: \"en {adj} {noun}\"",
