    "adj_p1_hero_title": "हामी डेनिस भाषामा वस्तुहरूको तुलना कसरी गर्छौं?",
    "adj_p1_hero_desc": "विशेषणहरूले कुनै व्यक्ति वा वस्तु कस्तो छ भनी वर्णन गर्छन्। जब हामी गुणहरूको तुलना वा विशेषता दर्शाउन चाहन्छौं, हामी विशेषणलाई <strong>तीन तार्किक चरणहरूमा</strong> रूप परिवर्तन गर्छौं:<br><strong>१. सामान्य रूप (Positiv):</strong> तुलना नगरी एउटा मात्र वस्तुको वर्णन गर्छ (जस्तै <em>en stor bil</em>)।<br><strong>२. तुलनात्मक रूप (Komparativ):</strong> <strong>दुई वस्तुहरूको</strong> तुलना गर्दा प्रयोग गरिन्छ। हामी प्रायः सधैं <strong>\"end\"</strong> शब्द प्रयोग गर्छौं (जस्तै <em>Bilen er <strong>større end</strong> cyklen</em>)।<br><strong>३. विजेता (Superlativ):</strong> जब कुनै वस्तु <strong>अरू सबैभन्दा अगाडि हुन्छ</strong> र सर्वोच्च स्तरमा पुग्छ तब प्रयोग गरिन्छ (जस्तै <em>Lastbilen er <strong>størst</strong></em>)।",
    "adj_p1_rule_thumb_label": "सजिलो नियम:",
    "adj_p1_rule_thumb_text": "Komparativ ले <strong>\"end\"</strong> को साथमा २ वस्तुहरूको तुलना गर्छ। Superlativ ले सबैलाई जित्ने विजेताको घोषणा गर्छ!",
    "adj_p1_s1_title_fagterm": "Positiv (सामान्य रूप)",
