    "adj_p1_s2_q": "के तपाईं दुई वस्तुहरूको तुलना गर्दै हुनुहुन्छ? (\"end\" शब्द खोज्नुहोस्)",
    "adj_p1_s2_ans": "हो ➔ -ere थप्नुहोस् वा स्वर वर्ण परिवर्तन गर्नुहोस् (\"større / hurtigere\")",
    "adj_p1_s2_badge_fagterm": "Komparativ (तुलनात्मक रूप)",
    "adj_p1_s2_badge_everyday": "२. २ वस्तुहरूको तुलना गर्छ",
