    "adj_p2_hero_title": "सुनौलो E-नियम: किन \"den store bil\" र \"min store bil\" भनिन्छ?",
    "adj_p2_hero_desc": "जब कुनै नाम अनिश्चित र अज्ञात हुन्छ, विशेषण आफ्नो सामान्य रूपमा रहन्छ (वा नपुंसक लिङ्गमा -t थपिन्छ):<br>• <strong>अनिश्चित (Ubestemt):</strong> <em>en stor bil</em> (fælleskøn) | <em>et stort hus</em> (intetkøn ले -t लिन्छ)।<br>• <strong>तर जब विषय निश्चित हुन्छ (BESTEMT):</strong> विषय ज्ञात हुनेबित्तिकै, तोकिँदा वा स्वामित्व दर्साउँदा, विशेषणको अन्त्यमा सधैं <strong>-e</strong> थप्नैपर्छ – चाहे त्यो fælleskøn होस् वा intetkøn!<br><em>den stor<strong>e</strong> bil</em> • <em>det stor<strong>e</strong> hus</em> • <em>min stor<strong>e</strong> bil</em> • <em>denne stor<strong>e</strong> bil</em>",
    "adj_p2_formula_title": "📐 विशेषणको निश्चित रूपको सूत्र:",
    "adj_p2_chip_marker_fagterm": "निश्चितता सूचक",
