    "adj_p2_formula_note": "💡 <strong>याद राख्नुहोस्:</strong> निश्चित रूपमा, नपुंसक लिङ्गले आफ्नो \"-t\" हटाउँछ (<em>et stor<strong>t</strong> hus</em> ➔ <em>det stor<strong>e</strong> hus</em> / <em>mit stor<strong>e</strong> hus</em>)!",
