    "adj_p2_super_def_title": "यसमा पनि सधैं -e थपिन्छ: \"Den største bil\" र \"Min bedste ven\"",
    "adj_p2_super_def_text": "जब सर्वोत्तम रूप (superlativ) को विशेषण निश्चित उपपद (<em>den/det/de</em>) वा सम्बन्धवाचक सर्वनाम (<em>min/din/vores</em>) सँग प्रयोग गरिन्छ, तब superlativ ले पनि अन्त्यमा <strong>-e</strong> प्रत्यय लिन्छ!<br>• एक्लै आउँदा: <em>Lastbilen er <strong>størst</strong>.</em><br>• निश्चित उपपदसँग: <em>Det er <strong>den største</strong> lastbil på vejen.</em><br>• स्वामित्व जनाउने शब्दसँग: <em>Peter er <strong>min bedste</strong> ven.</em>",
